      }).catch(fail);
    } catch (reason) { fail(reason); }

    return () => {
      disposed = true;
      abort.abort();
      unsubscribe();
      window.clearInterval(timer);
      document.removeEventListener('visibilitychange', onVisible);
      observer.disconnect();
      cancelAnimationFrame(frame);
      cancelAnimationFrame(resizeFrame);
      redraw.current = () => {};
