    onSamples([{timestamp: Date.now(), value: 80}]);
    await advance(1000);
    expect(chart.uplot.setData).toHaveBeenCalledTimes(before);
    await act(async () => pause.click());
    await advance();
    expect(chart.config.series[0].data.at(-1)).toBe(80);
  });
});
